#!/usr/bin/env node
/**
 * Validates SEO metadata in the static HTML generated by the production build.
 *
 * This intentionally uses only Node's standard library so the check can run
 * immediately after prerendering without adding a parser dependency to the
 * frontend bundle.
 */
import { readFile, readdir } from "node:fs/promises";
import { join, relative, resolve, sep } from "node:path";

const appRoot = resolve(import.meta.dirname, "..");
const cliDistRoot = process.argv.slice(2).find((argument) => argument !== "--");
const distRoot = resolve(cliDistRoot ?? join(appRoot, "dist", "public"));

function routeFromFile(filePath) {
  const route = relative(distRoot, filePath)
    .split(sep)
    .slice(0, -1)
    .join("/");
  return route ? `/${route}` : "/";
}

async function findHtmlFiles(directory) {
  const entries = await readdir(directory, { withFileTypes: true });
  const files = [];

  for (const entry of entries) {
    const entryPath = join(directory, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await findHtmlFiles(entryPath)));
    } else if (entry.isFile() && entry.name === "index.html") {
      files.push(entryPath);
    }
  }

  return files.sort();
}

function decodeHtml(value) {
  return value
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) =>
      String.fromCodePoint(Number.parseInt(code, 16)),
    )
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">");
}

function normalizeText(value) {
  return decodeHtml(value.replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim();
}

function parseAttributes(tag) {
  const attributes = new Map();
  const attributePattern =
    /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;

  for (const match of tag.matchAll(attributePattern)) {
    const [, name, doubleQuoted, singleQuoted, unquoted] = match;
    if (name.toLowerCase() === tag.slice(1).split(/\s|\//, 1)[0].toLowerCase()) {
      continue;
    }
    attributes.set(
      name.toLowerCase(),
      decodeHtml(doubleQuoted ?? singleQuoted ?? unquoted ?? ""),
    );
  }

  return attributes;
}

function findTags(html, tagName) {
  const pattern = new RegExp(`<${tagName}\\b[^>]*>`, "gi");
  return [...html.matchAll(pattern)].map((match) => ({
    raw: match[0],
    attributes: parseAttributes(match[0]),
    index: match.index,
  }));
}

function findTextElements(html, tagName) {
  const pattern = new RegExp(
    `<${tagName}\\b[^>]*>([\\s\\S]*?)<\\/${tagName}>`,
    "gi",
  );
  return [...html.matchAll(pattern)].map((match) => normalizeText(match[1]));
}

function getMetaContent(html, name) {
  return findTags(html, "meta")
    .filter((tag) => tag.attributes.get("name")?.toLowerCase() === name)
    .map((tag) => tag.attributes.get("content") ?? "");
}

function getCanonicalLinks(html) {
  return findTags(html, "link")
    .filter((tag) =>
      tag.attributes
        .get("rel")
        ?.toLowerCase()
        .split(/\s+/)
        .includes("canonical"),
    )
    .map((tag) => tag.attributes.get("href") ?? "");
}

function getJsonLdBlocks(html) {
  const pattern =
    /<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  return [...html.matchAll(pattern)].map((match) => match[1].trim());
}

const schemaFieldRules = {
  LocalBusiness: {
    name: "string",
    url: "url",
    logo: "media",
    image: "media",
    telephone: "string",
    description: "string",
    address: { kind: "schemaObject", types: ["PostalAddress"] },
  },
  WebPage: {
    name: "string",
    url: "url",
    headline: "string",
    description: "string",
    mainEntityOfPage: "reference",
    isPartOf: { kind: "schemaObject", types: ["WebSite"] },
  },
  Article: {
    headline: "string",
    description: "string",
    image: "media",
    author: { kind: "schemaObject", types: ["Person", "Organization"] },
    publisher: { kind: "schemaObject", types: ["Organization"] },
    mainEntityOfPage: "reference",
    url: "url",
  },
  WebSite: {
    name: "string",
    url: "url",
  },
  Organization: {
    name: "string",
  },
  BreadcrumbList: {
    itemListElement: "array",
  },
  PostalAddress: {
    streetAddress: "string",
    addressLocality: "string",
    addressCountry: "stringOrObject",
  },
  GeoCoordinates: {
    latitude: "number",
    longitude: "number",
  },
  OpeningHoursSpecification: {
    dayOfWeek: "stringOrArray",
    opens: "string",
    closes: "string",
  },
  ListItem: {
    position: "number",
    name: "string",
    item: "reference",
  },
};

const schemaRequiredFields = Object.fromEntries(
  Object.entries(schemaFieldRules).map(([type, fields]) => [type, Object.keys(fields)]),
);

function hasSchemaValue(value) {
  if (value === null || value === undefined) return false;
  if (typeof value === "string") return value.trim().length > 0;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === "object") return Object.keys(value).length > 0;
  return true;
}

function schemaTypes(value) {
  const types = value?.["@type"];
  if (Array.isArray(types)) return types.filter((type) => typeof type === "string");
  return typeof types === "string" ? [types] : [];
}

function isObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function isNonEmptyString(value) {
  return typeof value === "string" && value.trim().length > 0;
}

function isUrl(value) {
  if (!isNonEmptyString(value)) return false;

  try {
    const url = new URL(value);
    return ["http:", "https:"].includes(url.protocol);
  } catch {
    return false;
  }
}

function matchesSchemaFieldType(value, rule) {
  if (typeof rule === "string") {
    switch (rule) {
      case "string":
        return isNonEmptyString(value);
      case "url":
        return isUrl(value);
      case "media":
        return isNonEmptyString(value) || isObject(value);
      case "reference":
        return isUrl(value) || isObject(value);
      case "number":
        return typeof value === "number" && Number.isFinite(value);
      case "array":
        return Array.isArray(value) && value.length > 0;
      case "stringOrObject":
        return isNonEmptyString(value) || isObject(value);
      case "stringOrArray":
        return isNonEmptyString(value) || (Array.isArray(value) && value.length > 0);
      default:
        return true;
    }
  }

  if (!isObject(value)) return false;
  const actualTypes = schemaTypes(value);
  return rule.types.some((type) => actualTypes.includes(type));
}

function schemaFieldTypeDescription(rule) {
  if (typeof rule === "string") {
    return {
      string: "a non-empty string",
      url: "an absolute http(s) URL",
      media: "a non-empty string or object",
      reference: "an absolute http(s) URL or object",
      number: "a finite number",
      array: "a non-empty array",
      stringOrObject: "a non-empty string or object",
      stringOrArray: "a non-empty string or non-empty array",
    }[rule];
  }

  return `an object with @type ${rule.types.join(" or ")}`;
}

function validateSchemaField(node, type, field, rule, route, location, issues) {
  if (!matchesSchemaFieldType(node[field], rule)) {
    addIssue(
      issues,
      route,
      `${location} (${type}) field "${field}" must be ${schemaFieldTypeDescription(rule)}`,
    );
  }
}

function schemaNodes(value) {
  if (Array.isArray(value)) return value.flatMap(schemaNodes);
  if (!value || typeof value !== "object") return [];
  if (Array.isArray(value["@graph"])) return value["@graph"].flatMap(schemaNodes);
  return [value];
}

function validateNestedSchema(value, route, location, issues) {
  for (const node of schemaNodes(value)) {
    validateSchemaNode(node, route, location, issues);
  }
}

function validateSchemaNode(node, route, location, issues) {
  if (!isObject(node)) {
    addIssue(issues, route, `${location} must be an object`);
    return;
  }

  const types = schemaTypes(node);
  if (types.length === 0) {
    addIssue(issues, route, `${location} must contain @type`);
    return;
  }

  for (const type of types) {
    const requiredFields = schemaRequiredFields[type] ?? [];
    for (const field of requiredFields) {
      if (!hasSchemaValue(node[field])) {
        addIssue(issues, route, `${location} (${type}) is missing required field "${field}"`);
      } else {
        validateSchemaField(
          node,
          type,
          field,
          schemaFieldRules[type][field],
          route,
          location,
          issues,
        );
      }
    }

    if (type === "LocalBusiness") {
      validateNestedSchema(node.address, route, `${location}.address`, issues);
      validateNestedSchema(node.geo, route, `${location}.geo`, issues);
      validateNestedSchema(
        node.openingHoursSpecification,
        route,
        `${location}.openingHoursSpecification`,
        issues,
      );
    }

    if (type === "WebPage") {
      validateNestedSchema(node.isPartOf, route, `${location}.isPartOf`, issues);
    }

    if (type === "Article") {
      validateNestedSchema(node.author, route, `${location}.author`, issues);
      validateNestedSchema(node.publisher, route, `${location}.publisher`, issues);
      validateNestedSchema(node.isPartOf, route, `${location}.isPartOf`, issues);
    }

    if (type === "BreadcrumbList") {
      if (Array.isArray(node.itemListElement)) {
        node.itemListElement.forEach((item, index) => {
          validateNestedSchema(
            item,
            route,
            `${location}.itemListElement[${index}]`,
            issues,
          );
        });
      }
    }
  }
}

function addIssue(issues, route, message) {
  issues.push(`${route}: ${message}`);
}

function findDuplicates(valuesByRoute) {
  const routesByValue = new Map();

  for (const [route, value] of valuesByRoute) {
    const routes = routesByValue.get(value) ?? [];
    routes.push(route);
    routesByValue.set(value, routes);
  }

  return [...routesByValue.values()].filter((routes) => routes.length > 1);
}

async function main() {
  let htmlFiles;
  try {
    htmlFiles = await findHtmlFiles(distRoot);
  } catch (error) {
    if (error?.code === "ENOENT") {
      throw new Error(`Build output directory does not exist: ${distRoot}`);
    }
    throw error;
  }

  if (htmlFiles.length === 0) {
    throw new Error(`No generated index.html files found in ${distRoot}`);
  }

  const issues = [];
  const titles = [];
  const descriptions = [];

  for (const filePath of htmlFiles) {
    const route = routeFromFile(filePath);
    const html = await readFile(filePath, "utf8");
    const title = findTextElements(html, "title");
    const descriptionsForPage = getMetaContent(html, "description");
    const h1 = findTextElements(html, "h1");
    const canonical = getCanonicalLinks(html);
    const jsonLd = getJsonLdBlocks(html);

    if (title.length !== 1 || !title[0]) {
      addIssue(
        issues,
        route,
        `expected exactly one non-empty <title>, found ${title.length}`,
      );
    } else {
      titles.push([route, title[0]]);
    }

    if (
      descriptionsForPage.length !== 1 ||
      !normalizeText(descriptionsForPage[0])
    ) {
      addIssue(
        issues,
        route,
        `expected exactly one non-empty meta description, found ${descriptionsForPage.length}`,
      );
    } else {
      descriptions.push([route, normalizeText(descriptionsForPage[0])]);
    }

    if (h1.length !== 1 || !h1[0]) {
      addIssue(issues, route, `expected exactly one non-empty <h1>, found ${h1.length}`);
    }

    if (canonical.length !== 1 || !canonical[0]) {
      addIssue(
        issues,
        route,
        `expected exactly one non-empty canonical link, found ${canonical.length}`,
      );
    } else {
      try {
        const canonicalUrl = new URL(canonical[0]);
        if (!["http:", "https:"].includes(canonicalUrl.protocol)) {
          addIssue(issues, route, `canonical URL must use http or https: ${canonical[0]}`);
        }
        const normalizedRoute = route === "/" ? "/" : route.replace(/\/+$/, "");
        const normalizedCanonicalPath =
          canonicalUrl.pathname === "/"
            ? "/"
            : canonicalUrl.pathname.replace(/\/+$/, "");
        if (
          normalizedCanonicalPath !== normalizedRoute
        ) {
          const robots = getMetaContent(html, "robots").join(",").toLowerCase();
          if (!robots.includes("noindex")) {
            addIssue(
              issues,
              route,
              `canonical points to ${canonicalUrl.pathname}, so robots must contain noindex`,
            );
          }
        }
      } catch {
        addIssue(issues, route, `canonical URL is invalid: ${canonical[0]}`);
      }
    }

    if (jsonLd.length === 0) {
      addIssue(issues, route, "expected at least one JSON-LD script");
    } else {
      jsonLd.forEach((block, index) => {
        try {
          const value = JSON.parse(block);
          const values = Array.isArray(value) ? value : [value];
          if (
            values.length === 0 ||
            values.some(
              (item) =>
                !item ||
                typeof item !== "object" ||
                !item["@context"] ||
                (!item["@type"] && !item["@graph"]),
            )
          ) {
            addIssue(
              issues,
              route,
              `JSON-LD block ${index + 1} must contain @context and @type or @graph`,
            );
          } else {
            schemaNodes(value).forEach((node, nodeIndex) => {
              validateSchemaNode(
                node,
                route,
                `JSON-LD block ${index + 1}${nodeIndex > 0 ? ` node ${nodeIndex + 1}` : ""}`,
                issues,
              );
            });
          }
        } catch (error) {
          addIssue(
            issues,
            route,
            `JSON-LD block ${index + 1} is not valid JSON: ${error.message}`,
          );
        }
      });
    }
  }

  for (const [label, duplicates] of [
    ["title", findDuplicates(titles)],
    ["description", findDuplicates(descriptions)],
  ]) {
    for (const routes of duplicates) {
      addIssue(issues, "duplicate metadata", `${label} appears on ${routes.join(", ")}`);
    }
  }

  if (issues.length > 0) {
    console.error(`SEO validation failed with ${issues.length} issue(s):`);
    issues.forEach((issue) => console.error(`- ${issue}`));
    process.exitCode = 1;
    return;
  }

  console.log(`SEO validation passed for ${htmlFiles.length} generated route(s).`);
}

main().catch((error) => {
  console.error(`SEO validation failed: ${error.message}`);
  process.exitCode = 1;
});